SELECT id, shop_id, user_id, order_no, amount, pay_status, pay_method, pay_txn_no, paid_at,
       visit_time, items, created_at, updated_at
FROM order_record
WHERE user_id = #{userId}

    AND pay_status = #{payStatus}

ORDER BY created_at DESC

SELECT id, shop_id, user_id, order_no, amount, pay_status, pay_method, pay_txn_no, paid_at,
       visit_time, items, created_at, updated_at
FROM order_record
WHERE shop_id = #{shopId}

    AND pay_status = #{payStatus}

ORDER BY created_at DESC

SELECT COUNT(*)
FROM order_record
WHERE created_at >= #{startDate}
  AND created_at <= #{endDate}
